import React, { useEffect, useRef, useState } from 'react';
import { useAuth } from '@workspace/auth-web';
import { ArrowLeft, ArrowRight, BookOpen, Check, CheckCircle2, ChevronDown, Download, ExternalLink, FileText, FlaskConical, Layers3, Loader2, LockKeyhole, Search, ShieldCheck, Sparkles, UploadCloud } from 'lucide-react';
import MathText from './FormalMathText';
import FormalPreparedExample from './FormalPreparedExample';
import { pollFormalJob } from './formalJobPolling';
import { clearActiveJob, clearRetainedIntake, readActiveJob, readRetainedIntake, queryFormalJobId, recoverFormalIntake, rememberActiveJob, retainIntake, validModelId } from './formalIntakeRecovery';
import type { Expr, FormalInput, FormalPackage, FormalSubmission, IngestedSource, FormalJob, FormalSubject, FormalOutputs, CoverageResult } from '../../../api-server/src/formal/contract';
import './FormalLabPage.css';

type Step = 0 | 1 | 2 | 3 | 4;
type OutputTab = 'verification' | 'explanation' | 'review' | 'source' | 'field';
type AnalysisModel = { id: 'current' | 'sol' | 'argon'; label: string; model: string; provider: string; available: boolean; reason?: string };
type Catalog = { inputs: FormalInput[]; example: FormalPackage; exampleDigest: string; capabilities: { checker: string; scope: string[] }; models?: AnalysisModel[]; defaultModel?: string };
const STEPS = [{ title: 'Ingest the paper', short: 'Upload', icon: UploadCloud }, { title: 'Review the formalization', short: 'Formalize', icon: Sparkles }, { title: 'Approve this revision', short: 'Approve', icon: ShieldCheck }, { title: 'Verify and explain', short: 'Verify', icon: CheckCircle2 }, { title: 'Explore the results', short: 'Results', icon: BookOpen }];
const TABS: { id: OutputTab; title: string }[] = [{ id: 'verification', title: 'Verification' }, { id: 'explanation', title: 'Explanation' }, { id: 'review', title: 'Scientific review' }, { id: 'source', title: 'Source & log' }, { id: 'field', title: 'Field contribution' }];
const copy = <T,>(value: T): T => JSON.parse(JSON.stringify(value));
const shortDigest = (value?: string) => value ? `${value.slice(0, 12)}…${value.slice(-8)}` : 'Not saved';
const statusLabel = (status: string) => ({ checked: 'Symbolically checked', contradicted: 'Contradicted', unsupported: 'Unsupported', inconclusive: 'Inconclusive', partial: 'Partially checked', failed: 'Check failed', 'adopted-input': 'Adopted input', definition: 'Definition', interpretive: 'Interpretation', 'not-assessed': 'Not assessed', context: 'Context', 'conditional-checked': 'Conditional result', 'unverified-context': 'Unverified context', included: 'Included', 'already-represented': 'Already represented', conditional: 'Conditional contribution' }[status] || status);

class RequestError extends Error { constructor(message: string, readonly status: number) { super(message); } }
async function request<T>(path: string, body?: unknown): Promise<T> {
  const response = await fetch(`/api/formal-lab${path}`, { credentials: 'include', ...(body === undefined ? {} : { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }) });
  const data = await response.json().catch(() => ({ error: 'The server returned an unreadable response.' }));
  if (!response.ok) throw new RequestError(data.error || `Request failed (${response.status}).`, response.status);
  return data as T;
}
function ModelAttribution({ formalization, outputs }: { formalization: string | null | undefined; outputs?: string | null }) { return <div className="fl-ai-attribution"><span>AI formalization: <code>{formalization || 'No AI model recorded'}</code></span>{outputs && <span>{outputs === 'deterministic-report-v2' ? 'Output report' : 'AI explanation and review'}: <code>{outputs}</code></span>}</div>; }
function DateStamp({ value }: { value: string }) { const date = new Date(value); return <time dateTime={value}>{Number.isNaN(date.getTime()) ? value : date.toLocaleString(undefined, { year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}</time>; }
function SourceLink({ url, children }: { url?: string; children: React.ReactNode }) { return !url || (!/^https?:\/\//i.test(url) && !/^\/(?!\/)/.test(url)) ? <span>{children}</span> : <a href={url} target="_blank" rel="noopener noreferrer">{children}<ExternalLink size={12} aria-hidden="true" /></a>; }
function Status({ value }: { value: string }) { return <span className={`fl-status fl-status-${value}`}>{(value === 'checked' || value === 'conditional-checked') && <Check size={12} />}{statusLabel(value)}</span>; }
function modelLabel(name: string): string | null { const match = name.match(/^b([1-5])[_-]/); return match ? `Math context ${match[1]}` : null; }
function symbolLatex(name: string): string {
  name = name.replace(/^b[1-5]_/, '');
  const known: Record<string, string> = { pi: '\\pi', Pi: '\\Pi', kappa: '\\kappa', rho: '\\rho', theta: '\\theta', epsilon: '\\epsilon', delta: '\\delta', hbar: '\\hbar' };
  if (known[name]) return known[name];
  if (/^[A-Za-z]$/.test(name)) return name;
  const match = name.match(/^([A-Za-z]+)_(.+)$/);
  if (match) return `${known[match[1]] || (match[1].length === 1 ? match[1] : `\\mathrm{${match[1].replace(/[^A-Za-z0-9]/g, '')}}`)}_{\\mathrm{${match[2].replace(/[^A-Za-z0-9]/g, '')}}}`;
  return `\\mathrm{${name.replace(/[^A-Za-z0-9]/g, '')}}`;
}
function expressionLatex(expr: Expr, depth = 0): string {
  if (!expr || depth > 32) return '\\text{expression}';
  const next = (value: Expr) => expressionLatex(value, depth + 1);
  switch (expr.op) {
    case 'symbol': return symbolLatex(expr.name);
    case 'integer': return String(expr.value);
    case 'rational': return `\\frac{${expr.numerator}}{${expr.denominator}}`;
    case 'add': return expr.args.map(next).join(' + ');
    case 'mul': return expr.args.map(e => e.op === 'add' ? `\\left(${next(e)}\\right)` : next(e)).join(' \\, ');
    case 'div': return `\\frac{${next(expr.numerator)}}{${next(expr.denominator)}}`;
    case 'pow': return `{\\left(${next(expr.base)}\\right)}^{${expr.exponent}}`;
    case 'diff': return `\\frac{\\partial}{\\partial ${symbolLatex(expr.variable)}}\\left(${next(expr.expr)}\\right)`;
    case 'substitute': return `\\left.${next(expr.expr)}\\right|_{${Object.entries(expr.values).map(([symbol, value]) => `${symbolLatex(symbol)}=${next(value)}`).join(',\\;')}}`;
    default: return '\\text{unsupported expression}';
  }
}
function Equation({ lhs, rhs }: { lhs: Expr; rhs?: Expr }) { return <div className="fl-equation"><MathText text={`$$${expressionLatex(lhs)}${rhs ? ` = ${expressionLatex(rhs)}` : ''}$$`} /></div>; }
function LineReferences({ ids, onOpen }: { ids: string[]; onOpen: (ids: string[]) => void }) { return ids.length ? <span className="fl-line-refs">{ids.map(id => <button className="fl-line-ref" key={id} onClick={() => onOpen([id])} title={`Show source line ${id}`}>{id}</button>)}</span> : <span className="fl-unlinked">No source line linked</span>; }

function SourceDocument({ source, highlight, onOpen }: { source: IngestedSource; highlight?: string; onOpen: (ids: string[]) => void }) {
  const [filter, setFilter] = useState('');
  const lines = source.lines.filter(line => !filter.trim() || line.text.toLowerCase().includes(filter.toLowerCase()) || line.id.toLowerCase().includes(filter.toLowerCase()));
  useEffect(() => { if (highlight) setFilter(''); }, [highlight]);
  useEffect(() => { if (!highlight) return; const timer = window.setTimeout(() => document.getElementById(`source-line-${highlight}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 80); return () => clearTimeout(timer); }, [highlight, filter]);
  return <section className="fl-source-document"><div className="fl-section-heading"><div><h3>Numbered source</h3><p className="fl-muted">{source.filename} · {source.pageCount} {source.pageCount === 1 ? 'page' : 'pages'} · {source.lines.length} extracted lines</p></div><SourceLink url={source.fileUrl}>Original file</SourceLink></div>
    {source.warnings.length > 0 && <div className="fl-inline-note"><strong>Extraction notes</strong><ul>{source.warnings.map((item, i) => <li key={i}><MathText text={item} /></li>)}</ul></div>}
    <p className="fl-section-intro">Line numbers refer to extracted text, with page references back to the original. Inspect symbols and reading order before approving the formalization.</p>
    <label className="fl-source-search"><Search size={15} /><span className="fl-sr-only">Search extracted source</span><input value={filter} onChange={event => setFilter(event.target.value)} placeholder="Find a phrase, equation or line…" /></label>
    <div className="fl-numbered-source" role="region" aria-label="Extracted source with line numbers" tabIndex={0}>{lines.length ? lines.map(line => <div className={`fl-source-line ${highlight === line.id ? 'fl-source-highlight' : ''}`} key={line.id} id={`source-line-${line.id}`}><button onClick={() => onOpen([line.id])} className="fl-source-line-id" aria-label={`Source line ${line.id}, page ${line.page}`}>{line.id}</button><span className="fl-source-page">p. {line.page}</span><span className="fl-source-text"><MathText text={line.text || ' '} verbatim /></span></div>) : <p className="fl-source-no-match">No matching lines.</p>}</div>
    <details className="fl-details"><summary>Source identity and extraction record <ChevronDown size={15} /></summary><p>SHA-256 <code className="fl-full-digest">{source.sha256}</code></p><EventLog events={source.events} /></details>
  </section>;
}
function EventLog({ events }: { events: { at: string; stage: string; message: string }[] }) { return <ol className="fl-event-log">{events.map((event, index) => <li key={`${event.at}-${index}`}><span className="fl-event-dot" /><div><strong><MathText text={event.message} /></strong><span>{event.stage} · <DateStamp value={event.at} /></span></div></li>)}</ol>; }
function Coverage({ items, onOpen, onClaim }: { items: CoverageResult[]; onOpen: (ids: string[]) => void; onClaim?: (id: string) => void }) {
  const [role, setRole] = useState('all');
  const roles = [...new Set(items.map(item => item.role))];
  const visible = items.filter(item => role === 'all' || item.role === role);
  return <section className="fl-coverage"><div className="fl-section-heading"><h3>Claim-by-claim coverage</h3><span className="fl-counter">{items.length} source statements</span></div><p className="fl-section-intro">Every identified statement is accounted for. A physical premise or interpretation remains visible even when it cannot be established by symbolic algebra.</p><label className="fl-filter-label">Show <select value={role} onChange={event => setRole(event.target.value)}><option value="all">All statement types</option>{roles.map(item => <option key={item} value={item}>{item.replace(/-/g, ' ')}</option>)}</select></label><div className="fl-coverage-list">{visible.map(item => <article className="fl-coverage-item" key={item.id} id={`coverage-${item.id}`}><div className="fl-result-heading"><span className="fl-coverage-type">{item.role.replace(/-/g, ' ')}</span><Status value={item.status} /></div><p><MathText text={item.statement} /></p><div className="fl-coverage-reason"><MathText text={item.reason} /></div><LineReferences ids={item.sourceLineIds} onOpen={onOpen} />{item.checkedClaimIds.length > 0 && <div className="fl-evidence-links">Checked equations: {item.checkedClaimIds.map(id => onClaim ? <button className="fl-line-ref" key={id} onClick={() => onClaim(id)}>{id} <ArrowRight size={11} /></button> : <a key={id} href={`#formal-result-${id}`}>{id}</a>)}</div>}{item.unresolvedClaimIds.length > 0 && <p className="fl-muted">Unresolved: {item.unresolvedClaimIds.join(', ')}</p>}</article>)}</div></section>;
}

function PackagePreview({ packet, onOpen }: { packet: FormalPackage; onOpen: (ids: string[]) => void }) {
  const analysis = packet.analysis;
  const coverage = analysis?.coverage.map(item => ({ ...item, status: (item.role === 'physical-input' ? 'adopted-input' : item.role === 'definition' ? 'definition' : item.role === 'interpretation' ? 'interpretive' : 'not-assessed') as CoverageResult['status'], checkedClaimIds: [], unresolvedClaimIds: item.claimIds })) || [];
  return <div className="fl-packet"><section><h3>The central claim</h3><p><MathText text={packet.mainClaim} /></p></section><section><div className="fl-section-heading"><h3>Inputs proposed from the paper</h3><span className="fl-counter">{packet.selectedInputs.length} inputs</span></div><p className="fl-section-intro">These premises are adopted for the checks. Their source and physical justification must be reviewed separately.</p><div className="fl-reference-list">{packet.selectedInputs.map(input => { const ref = analysis?.inputReferences.find(item => item.inputId === input.id); return <article key={input.id}><div className="fl-reference-heading"><strong><MathText text={input.title} /></strong><span className="fl-counter">{ref?.basis || 'declared'}</span></div><p><MathText text={input.statement} /></p>{ref && <><p className="fl-muted"><MathText text={ref.justification} /></p><LineReferences ids={ref.sourceLineIds} onOpen={onOpen} /></>}{input.sourceUrl && <div className="fl-input-link"><SourceLink url={input.sourceUrl}>Cited source</SourceLink></div>}</article>; })}</div></section><section><h3>Assumptions and domains</h3><ol className="fl-assumptions">{packet.assumptions.map((item, i) => <li key={i}><MathText text={item} /></li>)}</ol></section>
    <details className="fl-details"><summary>Definitions and symbols <ChevronDown size={15} /></summary><div className="fl-definition-list fl-details-content">{packet.definitions.map((item, i) => <div key={`${item.symbol}-${i}`}>{modelLabel(item.symbol) && <span className="fl-model-label">{modelLabel(item.symbol)} · independent mathematical context</span>}<Equation lhs={{ op: 'symbol', name: item.symbol }} rhs={item.expression} /><p><MathText text={item.description} /></p></div>)}</div><div className="fl-table-scroll"><table><thead><tr><th>Symbol</th><th>Meaning</th><th>Domain</th><th>SI dimensions</th></tr></thead><tbody>{packet.symbols.map(item => <tr key={item.name}><td><MathText text={`$${symbolLatex(item.name)}$`} />{modelLabel(item.name) && <small className="fl-model-label">{modelLabel(item.name)}</small>}</td><td><MathText text={item.label} /></td><td><MathText text={item.domain} /></td><td><code>[{item.dimensions.join(', ')}]</code></td></tr>)}</tbody></table><p className="fl-muted">Dimension order: mass, length, time, current, temperature, amount, luminosity. Three entries use mass, length and time.</p></div></details>
    <section><div className="fl-section-heading"><h3>Exact claims proposed for checking</h3><span className="fl-counter">{packet.claims.length} equations</span></div><div className="fl-claims">{packet.claims.map((claim, index) => <article className="fl-claim" key={claim.id}><div className="fl-claim-heading"><span className="fl-claim-number">{String(index + 1).padStart(2, '0')}</span><h4><MathText text={claim.title} /></h4>{modelLabel(claim.id) && <span className="fl-model-badge">{modelLabel(claim.id)}</span>}</div><Equation lhs={claim.lhs} rhs={claim.rhs} /><p><MathText text={claim.explanation} /></p><LineReferences ids={analysis?.claimReferences.find(item => item.claimId === claim.id)?.sourceLineIds || []} onOpen={onOpen} /></article>)}</div></section>
    {coverage.length > 0 && <details className="fl-details"><summary>All identified source statements, including uncheckable claims <ChevronDown size={15} /></summary><div className="fl-details-content"><Coverage items={coverage} onOpen={onOpen} /></div></details>}
    <section className="fl-scope-note"><h3>What remains outside these checks</h3><ul>{packet.limitations.map((item, i) => <li key={i}><MathText text={item} /></li>)}</ul></section>
  </div>;
}

function OutputReport({ submission, tab, setTab, source, job, highlight, onOpen }: { submission: FormalSubmission; tab: OutputTab; setTab: (tab: OutputTab) => void; source: IngestedSource | null; job: FormalJob | null; highlight?: string; onOpen: (ids: string[]) => void }) {
  const revision = submission.currentRevision;
  const { package: packet, verification: report } = revision;
  const outputs = revision.outputs;
  const deterministic = outputs?.model === 'deterministic-report-v2';
  const liveEvents = job?.submissionId === submission.id ? job.events : [];
  const eventKeys = new Set<string>();
  const events = [...(source?.events || []), ...(packet.analysis?.ingestionLog || []), ...(outputs?.processingLog || []), ...liveEvents].filter(event => { const key = `${event.at}|${event.stage}|${event.message}`; if (eventKeys.has(key)) return false; eventKeys.add(key); return true; }).sort((a, b) => a.at.localeCompare(b.at));
  useEffect(() => { const button = document.getElementById(`output-tab-${tab}`); const parent = button?.parentElement; if (!button || !parent) return; const rect = button.getBoundingClientRect(); const bounds = parent.getBoundingClientRect(); if (rect.left < bounds.left || rect.right > bounds.right) parent.scrollTo({ left: parent.scrollLeft + rect.left - bounds.left - 12, behavior: 'smooth' }); }, [tab]);
  const checked = report?.claims.filter(claim => claim.status === 'checked').length || 0;
  const openClaim = (id: string) => { setTab('verification'); window.setTimeout(() => document.getElementById(`formal-result-${id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 50); };
  const exportEvidence = () => { const url = URL.createObjectURL(new Blob([JSON.stringify(submission, null, 2)], { type: 'application/json' })); const link = document.createElement('a'); link.href = url; link.download = 'formal-lab-evidence.json'; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 500); };
  return <div className="fl-report"><div className={`fl-report-banner ${report?.status === 'checked' ? 'fl-report-checked' : 'fl-report-partial'}`}><div className="fl-report-icon"><ShieldCheck size={27} /></div><div><div className="fl-eyebrow">INDEPENDENT VERIFICATION · REVISION {revision.revision}</div><h2>{checked} of {report?.claims.length || 0} equations symbolically checked</h2><p>Checked mathematics is conditional on the declared inputs. This count does not mean the entire paper is verified.</p></div></div>
    {outputs && <div className="fl-summary-grid"><div><strong>{outputs.summary.total}</strong><span>source statements</span></div><div><strong>{outputs.summary.checked}</strong><span>checked statements</span></div><div><strong>{outputs.summary.conditionalInputs}</strong><span>adopted inputs</span></div><div><strong>{outputs.summary.unresolved}</strong><span>unresolved statements</span></div></div>}
    <div className="fl-report-meta"><span>{report?.checker || 'Checker'} · {report?.engine || 'Report pending'}</span>{report && <span><DateStamp value={report.checkedAt} /></span>}<button className="fl-text-button" onClick={exportEvidence}><Download size={13} /> Download full evidence</button></div>
    <ModelAttribution formalization={revision.model} outputs={outputs?.model} />
    <div className="fl-output-tabs" role="tablist" aria-label="Submission output">{TABS.map((item, index) => <button key={item.id} id={`output-tab-${item.id}`} role="tab" aria-selected={tab === item.id} aria-controls={`output-panel-${item.id}`} tabIndex={tab === item.id ? 0 : -1} onClick={() => setTab(item.id)} onKeyDown={event => { if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const next = event.key === 'Home' ? 0 : event.key === 'End' ? TABS.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + TABS.length) % TABS.length; setTab(TABS[next].id); document.getElementById(`output-tab-${TABS[next].id}`)?.focus(); }}>{item.title}</button>)}</div>
    <div className="fl-output-panel" id={`output-panel-${tab}`} role="tabpanel" aria-labelledby={`output-tab-${tab}`}>
      {deterministic && (tab === 'explanation' || tab === 'review') && <div className="fl-inline-note">AI explanation generation did not complete; this is a deterministic evidence report from the actual checks.</div>}
      {tab === 'verification' && <><div className="fl-section-heading"><h3>The mathematical evidence</h3><span className="fl-counter">AI cannot mark a check as passed</span></div><div className="fl-result-list">{report?.claims.map(result => { const claim = packet.claims.find(item => item.id === result.id); return <article className="fl-result" key={result.id} id={`formal-result-${result.id}`}><div className="fl-result-heading"><h4><MathText text={result.title} />{modelLabel(result.id) && <span className="fl-model-badge">{modelLabel(result.id)}</span>}</h4><Status value={result.status} /></div>{claim && <Equation lhs={claim.lhs} rhs={claim.rhs} />}<p><MathText text={result.message} /></p><LineReferences ids={packet.analysis?.claimReferences.find(item => item.claimId === result.id)?.sourceLineIds || []} onOpen={onOpen} /><div className="fl-result-facts"><span>Dimensions: <strong>{result.dimensions}</strong></span><span>Residual: <code>{result.residual || '—'}</code></span>{result.derivationKind && <span>{result.derivationKind === 'definition-restatement' ? 'Definition restatement' : 'Derived identity'}</span>}</div>{result.domainRestrictions.length > 0 && <div className="fl-domain"><strong>Required domain</strong><ul>{result.domainRestrictions.map((item, i) => <li key={i}><MathText text={item} /></li>)}</ul></div>}{result.steps && <details className="fl-details"><summary>Show deterministic checking steps <ChevronDown size={14} /></summary><ol className="fl-check-steps">{result.steps.map((item, i) => <li key={i}><code>{item}</code></li>)}</ol></details>}</article>; })}</div>{outputs && <Coverage items={outputs.coverage} onOpen={onOpen} onClaim={openClaim} />}<section className="fl-scope-note"><h3>Limits of the verification</h3><ul>{[...new Set([...packet.limitations, ...(report?.limitations || [])])].map((item, i) => <li key={i}><MathText text={item} /></li>)}</ul></section></>}
      {tab === 'explanation' && (outputs ? <section className="fl-generated-explanation"><div className="fl-eyebrow">EXPLANATION AFTER VERIFICATION</div><h2><MathText text={packet.title} /></h2><p className="fl-section-intro">Each section names its mathematical support and adopted inputs. {deterministic ? 'The text reports the actual checking evidence and remains open to scientific review.' : 'The prose is AI-generated and remains open to scientific review.'}</p><p className="fl-generation-note">{deterministic ? 'Report generator' : 'Explanation model'}: <code>{outputs.model}</code></p>{outputs.explanation.map(section => <article className="fl-explanation-section" key={section.id} id={`explanation-${section.id}`}><div className="fl-result-heading"><h3><MathText text={section.title} /></h3><Status value={section.status} /></div><p><MathText text={section.text} /></p><div className="fl-evidence-links">{section.claimIds.map(id => <button key={id} className="fl-line-ref" onClick={() => { setTab('verification'); window.setTimeout(() => document.getElementById(`formal-result-${id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 50); }}>{id} <ArrowRight size={11} /></button>)}</div><LineReferences ids={section.sourceLineIds} onOpen={onOpen} />{section.inputIds.length > 0 && <p className="fl-muted">Conditional inputs: {section.inputIds.join(', ')}</p>}</article>)}</section> : <Unavailable text="The explanation has not been generated yet. Run “Verify and build outputs” to produce it from the checker’s actual findings." />)}
      {tab === 'review' && (outputs ? <ScientificReview outputs={outputs} onClaim={id => { setTab('verification'); window.setTimeout(() => document.getElementById(`formal-result-${id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 50); }} /> : <Unavailable text="The scientific review will be generated after verification, with direct references to the actual findings." />)}
      {tab === 'source' && <><div className="fl-section-heading"><h3>Ingestion and processing record</h3><span className="fl-counter">Source-linked audit trail</span></div><p className="fl-section-intro">This record shows extraction and processing events, source coverage, and deterministic checking steps. It is an evidence log, rather than an AI’s private reasoning.</p>{events.length > 0 && <EventLog events={events} />}{source ? <SourceDocument source={source} highlight={highlight} onOpen={onOpen} /> : <Unavailable text="This older prepared submission has no numbered uploaded source. Its source excerpt is preserved in the exact package." />}{outputs && <Coverage items={outputs.coverage} onOpen={onOpen} onClaim={openClaim} />}</>}
      {tab === 'field' && <FieldContributions outputs={outputs} packet={packet} published={Boolean(revision.publishConsent)} />}
    </div>
    {outputs?.warnings.length ? <section className="fl-scope-note"><h3>Output notes</h3><ul>{outputs.warnings.map((item, i) => <li key={i}><MathText text={item} /></li>)}</ul></section> : null}
    <details className="fl-details"><summary>Exact revision and reproducibility <ChevronDown size={15} /></summary><p>Approval and results apply to this immutable package digest. Editing the inputs or claims creates a revision that requires a new approval.</p><code className="fl-full-digest">SHA-256 {revision.digest}</code><p>Approved {revision.approvedAt ? <DateStamp value={revision.approvedAt} /> : 'not yet'} · Output {outputs ? <DateStamp value={outputs.generatedAt} /> : 'not generated'}</p><p>Source: <SourceLink url={packet.source.url}><MathText text={packet.source.title} /></SourceLink></p></details>
  </div>;
}
function Unavailable({ text }: { text: string }) { return <div className="fl-unavailable"><BookOpen size={26} /><p><MathText text={text} /></p></div>; }
function ScientificReview({ outputs, onClaim }: { outputs: FormalOutputs; onClaim: (id: string) => void }) {
  const review = outputs.review;
  return <section className="fl-scientific-review"><div className="fl-review-masthead"><div><div className="fl-eyebrow">SCIENTIFIC REVIEW</div><h2>Assessment grounded in the checks</h2><p>Verification-informed review · <DateStamp value={outputs.generatedAt} /> · <code>{outputs.model}</code></p></div><span className="fl-review-badge"><ShieldCheck size={15} /> Evidence linked</span></div><div className="fl-review-summary"><MathText text={review.summary} /></div><div className="fl-review-cards"><article><span>01 / EXPLANATION</span><h3>Explanatory contribution</h3><p><MathText text={review.explanatoryContribution} /></p></article><article><span>02 / MATHEMATICS</span><h3>Correctness and coverage</h3><p><MathText text={review.correctness} /></p></article><article><span>03 / PHYSICS</span><h3>Physical justification</h3><p><MathText text={review.physicalJustification} /></p></article></div><article className="fl-review-section"><h3>Relationship to prior work</h3><p><MathText text={review.priorWork} /></p></article><div className="fl-review-columns"><article><h3>Strengths</h3><ul>{review.strengths.map((item, i) => <li key={i}><MathText text={item} /></li>)}</ul></article><article><h3>Open questions</h3><ul>{review.openQuestions.map((item, i) => <li key={i}><MathText text={item} /></li>)}</ul></article></div><article className="fl-review-recommendation"><h3>Assessment</h3><p><MathText text={review.recommendation} /></p></article><div className="fl-evidence-links">Referenced checks: {review.claimIds.map(id => <button key={id} className="fl-line-ref" onClick={() => onClaim(id)}>{id} <ArrowRight size={11} /></button>)}</div><p className="fl-muted">This review is separate from the main site’s reviews. {outputs.model === 'deterministic-report-v2' ? 'The evidence report does not establish empirical validity or novelty on its own.' : 'The AI assessment does not establish empirical validity or novelty on its own.'}</p></section>;
}
function FieldContributions({ outputs, packet, published }: { outputs?: FormalOutputs | null; packet: FormalPackage; published: boolean }) {
  return <section className="fl-field-output"><div className="fl-eyebrow">FROM ONE PAPER TO A SHARED EXPLANATION</div><h2><MathText text={packet.analysis?.subjectTitle || 'A growing subject account'} /></h2><p className="fl-section-intro">Every eligible contribution retains its source, checked claims and conditions. Overlapping results can be represented together without presenting repeated contributions as independent verification.</p><div className="fl-inline-note">{published ? 'You authorized publication of this revision’s source and results. The dispositions below show what was actually added to the subject account.' : 'This submission is private. Public field publication requires the author’s separate checkbox when approving the revision.'}</div>{outputs?.contributions.length ? outputs.contributions.map(item => <article className="fl-contribution" key={item.id}><div className="fl-result-heading"><h3><MathText text={item.title} /></h3><Status value={item.disposition} /></div><p><MathText text={item.text} /></p><div className="fl-coverage-reason"><MathText text={item.reason} /></div><div className="fl-evidence-links">{item.claimIds.map(id => <span className="fl-line-ref" key={id}>{id}</span>)}</div><a className="fl-subject-link" href={`${item.subjectUrl}${item.paragraphId && !item.subjectUrl.includes('#') ? `#${item.paragraphId}` : ''}`}>{item.paragraphId ? 'View placement in the subject explanation' : 'Open subject account'} <ArrowRight size={14} /></a></article>) : <Unavailable text={outputs ? 'No contribution has been included in the public subject account for this revision.' : 'The system proposes field contributions after verification and explanation generation.'} />}{packet.analysis?.subjectSlug && <a href={`/formal-lab/subjects/${encodeURIComponent(packet.analysis.subjectSlug)}`} className="fl-button fl-button-ghost">Open <MathText text={packet.analysis.subjectTitle} /> <ArrowRight size={14} /></a>}</section>;
}

async function rememberFile(file: File | null): Promise<void> {
  await new Promise<void>((resolve, reject) => { const open = indexedDB.open('formal-lab-pending', 1); open.onupgradeneeded = () => open.result.createObjectStore('files'); open.onerror = () => reject(open.error); open.onsuccess = () => { const db = open.result; const tx = db.transaction('files', 'readwrite'); if (file) tx.objectStore('files').put(file, 'draft'); else tx.objectStore('files').delete('draft'); tx.oncomplete = () => { db.close(); resolve(); }; tx.onerror = () => { db.close(); reject(tx.error); }; }; });
}
async function restoreFile(): Promise<File | null> {
  return new Promise((resolve) => { const open = indexedDB.open('formal-lab-pending', 1); open.onupgradeneeded = () => open.result.createObjectStore('files'); open.onerror = () => resolve(null); open.onsuccess = () => { const db = open.result; const tx = db.transaction('files', 'readonly'); const get = tx.objectStore('files').get('draft'); get.onsuccess = () => { const value = get.result; resolve(value instanceof File ? value : null); }; get.onerror = () => resolve(null); tx.oncomplete = () => db.close(); }; });
}
async function fileBase64(file: File): Promise<string> { const bytes = new Uint8Array(await file.arrayBuffer()); let encoded = ''; for (let start = 0; start < bytes.length; start += 32768) encoded += String.fromCharCode(...bytes.subarray(start, start + 32768)); return btoa(encoded); }

function LabHeader({ signedIn, loading, signIn }: { signedIn?: string; loading: boolean; signIn: () => void }) { return <header className="fl-header"><div className="fl-header-inner"><a href="/" className="fl-brand" aria-label="Modern Science Review home">ModernScience<span>.</span>Review</a><a href="/formal-lab" className="fl-lab-wordmark"><FlaskConical size={14} /> Formal Lab <span><b className="fl-version-prefix">Prototype </b>v2</span></a><div className="fl-header-actions"><a href="/" className="fl-home-link"><ArrowLeft size={14} /> Main site</a>{!loading && (signedIn ? <span className="fl-account">{signedIn}</span> : <button className="fl-button fl-button-small fl-button-ghost" onClick={signIn}>Sign in</button>)}</div></div></header>; }
function SubjectEvidence({ subject }: { subject: FormalSubject }) {
  return <article className="fl-subject-article">{subject.paragraphs.map(item => <section key={item.id} id={item.id}><Status value={item.status} /><h2><MathText text={item.title} /></h2><p><MathText text={item.text} /></p>{item.conditions?.length ? <details className="fl-details"><summary>Inputs and conditions <ChevronDown size={15} /></summary><div className="fl-details-content"><ul className="fl-subject-conditions">{item.conditions.map((condition, index) => <li key={index}><MathText text={condition} /></li>)}</ul></div></details> : null}<details className="fl-details"><summary>{item.sources.length} supporting {item.sources.length === 1 ? 'submission' : 'submissions'} and exact evidence <ChevronDown size={15} /></summary><div className="fl-details-content">{item.sources.map(source => <div className="fl-field-citation" key={`${source.submissionId}-${source.revisionId}`}><a href={`/formal-lab?submission=${encodeURIComponent(source.submissionId)}`}><MathText text={source.title} /> <ArrowRight size={12} /></a><p>Checks: {source.claimIds.join(', ') || 'None linked'}</p><p>Source lines: {source.sourceLineIds.join(', ') || 'None linked'}</p><p>Revision <code>{shortDigest(source.digest)}</code> · <SourceLink url={source.sourceUrl}>Source file</SourceLink></p></div>)}</div></details></section>)}</article>;
}
function SubjectPage({ slug }: { slug: string }) {
  const { user, isLoading } = useAuth();
  const [subject, setSubject] = useState<FormalSubject | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [evidenceOpen, setEvidenceOpen] = useState(Boolean(window.location.hash));
  const overview = subject?.overview && subject.overview.sourceVersion === subject.version ? subject.overview : null;
  useEffect(() => { let active = true; request<FormalSubject>(`/subjects/${encodeURIComponent(slug)}`).then(value => { if (active) setSubject(value); }).catch(err => { if (active) setError(err.message); }); return () => { active = false; }; }, [slug]);
  useEffect(() => { if (subject && window.location.hash) { setEvidenceOpen(true); window.setTimeout(() => document.getElementById(decodeURIComponent(window.location.hash.slice(1)))?.scrollIntoView({ block: 'center' }), 100); } }, [subject]);
  const openEvidence = (id: string) => { setEvidenceOpen(true); window.setTimeout(() => document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 90); };
  return <div className="fl"><LabHeader signedIn={user ? user.firstName || user.email || 'Signed in' : undefined} loading={isLoading} signIn={() => { window.location.href = `/api/login?returnTo=${encodeURIComponent(window.location.pathname)}`; }} /><main><div className="fl-subject-container"><a href="/formal-lab" className="fl-text-button"><ArrowLeft size={14} /> Submission workspace</a>
    <div className="fl-subject-heading"><div className="fl-eyebrow">A SOURCE-LINKED, EVOLVING FIELD EXPLANATION</div><h1><MathText text={subject?.title || slug.replace(/-/g, ' ')} /></h1><p>Mathematical contributions from author-approved submissions, with their assumptions and verification evidence preserved.</p>{subject && <div className="fl-subject-meta">Version {subject.version} · Updated <DateStamp value={subject.updatedAt} /> · {subject.paragraphs.length} {subject.paragraphs.length === 1 ? 'contribution' : 'contributions'}</div>}</div>
    {error && <div className="fl-alert fl-alert-error" role="alert"><MathText text={error} /></div>}{!subject && !error && <div className="fl-loading"><Loader2 size={24} className="fl-spin" />Loading the subject explanation…</div>}
    {subject && <><div className="fl-inline-note"><strong>An emerging conditional account.</strong> Each included result passed the listed symbolic checks under its stated inputs. Publication here does not establish all physical premises, experimental validity, or an exhaustive account of the field.</div>
      {subject.paragraphs.length ? <>
        {overview ? <><div className="fl-subject-layout"><aside className="fl-subject-toc"><strong>In this explanation</strong>{overview.sections.map((item, i) => <a key={item.id} href={`#overview-${item.id}`}><span>{String(i + 1).padStart(2, '0')}</span><MathText text={item.title} /></a>)}</aside><article className="fl-subject-article fl-subject-overview"><div className="fl-eyebrow">COMPILED SUBJECT EXPLANATION</div><p className="fl-subject-introduction"><MathText text={overview.introduction} /></p>{overview.sections.map(section => <section key={section.id} id={`overview-${section.id}`}><h2><MathText text={section.title} /></h2><p><MathText text={section.text} /></p><div className="fl-evidence-links">Supporting contributions {section.paragraphIds.map(id => <a key={id} href={`#${id}`} onClick={() => openEvidence(id)}><MathText text={subject.paragraphs.find(item => item.id === id)?.title || id} /> <ArrowRight size={11} /></a>)}</div></section>)}<p className="fl-overview-provenance">Compiled from subject version {overview.sourceVersion} · <DateStamp value={overview.generatedAt} /> · AI synthesis; linked checks verify the mathematics under their stated conditions.</p></article></div><details className="fl-evidence-pool fl-details" open={evidenceOpen} onToggle={event => setEvidenceOpen(event.currentTarget.open)}><summary><span><strong>Inspect the underlying contributions</strong><small>{subject.paragraphs.length} source-linked {subject.paragraphs.length === 1 ? 'result' : 'results'}, with assumptions and exact verification evidence</small></span><ChevronDown size={17} /></summary><SubjectEvidence subject={subject} /></details></> : <><div className="fl-subject-pool-heading"><h2>Conditional contributions</h2><p>The source-linked evidence is shown below. A compiled narrative is not available for this subject version yet.</p></div><div className="fl-subject-layout"><aside className="fl-subject-toc"><strong>Available contributions</strong>{subject.paragraphs.map((item, i) => <a key={item.id} href={`#${item.id}`}><span>{String(i + 1).padStart(2, '0')}</span><MathText text={item.title} /></a>)}</aside><SubjectEvidence subject={subject} /></div></>}
      </> : <div className="fl-panel fl-empty-subject"><Layers3 size={32} /><h2>The account starts with its first published contribution</h2><p>Upload a paper, inspect and approve the formalization, then choose whether to publish its checked results here.</p><a href="/formal-lab" className="fl-button fl-button-primary">Submit a paper <ArrowRight size={14} /></a></div>}
    </>}
  </div></main></div>;
}

function SubmissionWorkspace() {
  const { user, isLoading: authLoading } = useAuth();
  const [catalog, setCatalog] = useState<Catalog | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [modelId, setModelId] = useState(() => { try { return sessionStorage.getItem('formal-lab-analysis-model') || 'current'; } catch { return 'current'; } });
  const [source, setSource] = useState<IngestedSource | null>(null);
  const [submission, setSubmission] = useState<FormalSubmission | null>(null);
  const [submissions, setSubmissions] = useState<FormalSubmission[]>([]);
  const [packet, setPacket] = useState<FormalPackage | null>(null);
  const [title, setTitle] = useState('');
  const [authors, setAuthors] = useState('');
  const [mainClaim, setMainClaim] = useState('');
  const [subjectSlug, setSubjectSlug] = useState('');
  const [step, setStep] = useState<Step>(0);
  const [tab, setTab] = useState<OutputTab>('verification');
  const [job, setJob] = useState<FormalJob | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [restoring, setRestoring] = useState(false);
  const [recoveryStore] = useState(() => { try { return sessionStorage; } catch { return null; } });
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [approvedIntent, setApprovedIntent] = useState(false);
  const [publishIntent, setPublishIntent] = useState(false);
  const [jsonDraft, setJsonDraft] = useState('');
  const [showSource, setShowSource] = useState(false);
  const [highlight, setHighlight] = useState<string>();
  const [dragging, setDragging] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const workspace = useRef<HTMLDivElement>(null);
  const busyRef = useRef(false);
  const previousStep = useRef<Step>(0);
  const restoreEpoch = useRef(0);
  const modelEpoch = useRef(0);
  const currentOwner = useRef(user?.id);
  currentOwner.current = user?.id;
  const previousOwner = useRef<string | null | undefined>(undefined);
  const mounted = useRef(true);
  const invalidateRestore = () => { restoreEpoch.current++; setRestoring(false); };
  const forgetIntake = () => { if (user?.id) { clearRetainedIntake(recoveryStore, user.id); clearActiveJob(recoveryStore, user.id); } };
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; restoreEpoch.current++; }; }, []);
  const polling = Boolean(job && (job.status === 'queued' || job.status === 'running'));
  const working = Boolean(busy) || polling || restoring;
  const advancedDirty = Boolean(packet && JSON.stringify(packet, null, 2) !== jsonDraft);
  const approved = Boolean(submission?.currentRevision.approvedAt) && !advancedDirty;
  const analysisModels = catalog?.models || [];
  const selectedModel = analysisModels.find(model => model.id === modelId);
  const modelUnavailable = analysisModels.length > 0 && (!selectedModel || !selectedModel.available);
  const chooseModel = (id: string) => { modelEpoch.current++; setModelId(id); try { sessionStorage.setItem('formal-lab-analysis-model', id); } catch { /* Model selection still works without browser storage. */ } };
  const requireModel = () => { if (modelUnavailable) throw new Error(selectedModel?.reason || 'Choose an available analysis model before starting.'); };

  const takeSubmission = (next: FormalSubmission) => { invalidateRestore(); if (user?.id) clearRetainedIntake(recoveryStore, user.id); setSelectedFile(null); setSubmission(next); setPacket(copy(next.currentRevision.package)); setJsonDraft(JSON.stringify(next.currentRevision.package, null, 2)); setSource(next.sourceDocument || null); setTitle(next.title); setAuthors(next.currentRevision.package.authors); setApprovedIntent(false); setPublishIntent(Boolean(next.currentRevision.publishConsent)); setSubmissions(items => [next, ...items.filter(item => item.id !== next.id)]); };
  const openSubmission = async (id: string, updateUrl = true) => { invalidateRestore(); const next = await request<FormalSubmission>(`/submissions/${encodeURIComponent(id)}`); takeSubmission(next); setStep(next.currentRevision.verification ? 4 : next.currentRevision.approvedAt ? 3 : 1); if (updateUrl) window.history.pushState({}, '', `/formal-lab?submission=${encodeURIComponent(next.id)}`); };
  useEffect(() => { let active = true; const epoch = restoreEpoch.current; request<Catalog>('/catalog').then(value => { if (!active) return; setCatalog(value); setModelId(current => current === 'current' ? value.defaultModel || 'current' : current); }).catch(() => {}); restoreFile().then(file => { if (active && epoch === restoreEpoch.current && file) setSelectedFile(file); }); return () => { active = false; }; }, []);
  useEffect(() => { if (authLoading) return; let active = true; const load = () => { const id = new URLSearchParams(window.location.search).get('submission'); if (id) request<FormalSubmission>(`/submissions/${encodeURIComponent(id)}`).then(next => { if (!active) return; takeSubmission(next); setStep(next.currentRevision.verification ? 4 : next.currentRevision.approvedAt ? 3 : 1); }).catch(err => { if (active) setError(err.message); }); }; load(); window.addEventListener('popstate', load); return () => { active = false; window.removeEventListener('popstate', load); }; }, [authLoading, user?.id]);
  useEffect(() => {
    if (authLoading) return;
    const owner = user?.id || null;
    if (previousOwner.current !== undefined && previousOwner.current !== owner) {
      invalidateRestore();
      if (previousOwner.current) { clearRetainedIntake(recoveryStore, previousOwner.current); clearActiveJob(recoveryStore, previousOwner.current); }
      setSelectedFile(null); setSource(null); setSubmission(null); setPacket(null); setJob(null); setJsonDraft(''); setTitle(''); setAuthors(''); setMainClaim(''); setSubjectSlug(''); setApprovedIntent(false); setPublishIntent(false); setShowSource(false); setStep(0); setError(null); setNotice(null); void rememberFile(null).catch(() => {});
    }
    previousOwner.current = owner;
    if (!owner) { setSubmissions([]); return; }
    let active = true;
    const explicitSubmission = new URLSearchParams(window.location.search).get('submission');
    const reference = readRetainedIntake(recoveryStore, owner), activeJobId = (!explicitSubmission && queryFormalJobId(window.location.search)) || readActiveJob(recoveryStore, owner);
    if (!explicitSubmission && (reference || activeJobId)) restoreEpoch.current++;
    const epoch = restoreEpoch.current, selectionEpoch = modelEpoch.current;
    const isCurrent = () => active && mounted.current && currentOwner.current === owner && restoreEpoch.current === epoch;
    request<{ submissions: FormalSubmission[] }>('/submissions').then(data => { if (isCurrent()) setSubmissions(data.submissions); }).catch(() => {});
    if (!explicitSubmission && (reference || activeJobId)) {
      setRestoring(true);
      void recoverFormalIntake({ reference, activeJobId, readJob: id => request<FormalJob>(`/jobs/${encodeURIComponent(id)}`), readSource: id => request<IngestedSource>(`/sources/${encodeURIComponent(id)}`), isCurrent }).then(recovered => {
        if (!recovered || !isCurrent()) return;
        if (recovered.jobError) clearActiveJob(recoveryStore, owner);
        if (recovered.source) {
          setSelectedFile(null); setSource(recovered.source); setSubmission(null); setPacket(null); setJsonDraft(''); setApprovedIntent(false); setPublishIntent(false); setShowSource(true); setStep(0);
          const restoredModel = recovered.modelId;
          if (validModelId(restoredModel) && modelEpoch.current === selectionEpoch) { setModelId(restoredModel); try { sessionStorage.setItem('formal-lab-analysis-model', restoredModel); } catch {} }
          retainIntake(recoveryStore, owner, { sourceId: recovered.source.id, ...(restoredModel ? { modelId: restoredModel } : {}), ...(recovered.job?.kind === 'analyze' ? { jobId: recovered.job.id } : {}) });
          setNotice('Your uploaded source has been restored. Inspect it and choose Analyze the complete paper to start a new attempt; no analysis has been started automatically.');
        }
        if (recovered.job) setJob(recovered.job);
        if (recovered.sourceError) {
          if (recovered.sourceError instanceof RequestError && [403, 404].includes(recovered.sourceError.status)) clearRetainedIntake(recoveryStore, owner);
          setError('The previous uploaded source could not be restored for this account. Choose your paper file again to continue.'); setNotice('Choose your paper file again below. The system will not start another analysis until you request it.');
        } else if (!recovered.source && recovered.jobError) setError('The previous attempt could not be restored for this account. Choose your paper file again to continue.');
      }).finally(() => { if (isCurrent()) setRestoring(false); });
    }
    return () => { active = false; };
  }, [authLoading, user?.id]);
  useEffect(() => {
    const owner = user?.id, submissionId = submission?.id;
    if (!owner || !submissionId) return;
    const pending = queryFormalJobId(window.location.search) || readActiveJob(recoveryStore, owner);
    if (!pending || pending === job?.id) return;
    let active = true;
    const epoch = restoreEpoch.current;
    request<FormalJob>(`/jobs/${encodeURIComponent(pending)}`).then(value => { if (active && mounted.current && currentOwner.current === owner && restoreEpoch.current === epoch && value.kind === 'process' && value.submissionId === submissionId) setJob(value); }).catch(() => {});
    return () => { active = false; };
  }, [user?.id, submission?.id, job?.id]);
  useEffect(() => {
    if (!job) return;
    if (job.status === 'failed') { setError(job.error || 'This attempt stopped. Completed drafts remain under Your saved submissions.'); if (user?.id) clearActiveJob(recoveryStore, user.id); if (job.kind === 'analyze') { setStep(0); if (source?.id === job.sourceId) setNotice('Your uploaded source is ready below. Review the selected model, then choose Retry analysis to start a new attempt.'); } return; }
    if (job.status === 'complete') { if (user?.id) clearActiveJob(recoveryStore, user.id); if (job.submissionId) { let active = true; request<FormalSubmission>(`/submissions/${encodeURIComponent(job.submissionId)}`).then(next => { if (!active) return; takeSubmission(next); setStep(job.kind === 'analyze' ? 1 : 4); if (job.kind === 'process') setTab('verification'); setNotice(job.kind === 'analyze' ? 'The complete source was analyzed. Review the proposed inputs, exact equations, and coverage before approving.' : 'Verification and the evidence-linked outputs are ready.'); window.history.replaceState({}, '', `/formal-lab?submission=${encodeURIComponent(next.id)}`); }).catch(err => { if (active) setError(err.message); }); return () => { active = false; }; } return; }
    return pollFormalJob({ read: () => request<FormalJob>(`/jobs/${encodeURIComponent(job.id)}`), onValue: value => { setJob(value); setError(null); }, onError: err => setError(`Progress could not be refreshed: ${err instanceof Error ? err.message : 'Connection interrupted'}. The job may still be running; progress will be retried.`) });
  }, [job?.id, job?.status, user?.id]);
  useEffect(() => { if (previousStep.current === step) return; previousStep.current = step; workspace.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }); document.getElementById('formal-stage-title')?.focus({ preventScroll: true }); }, [step]);
  const run = async (label: string, action: () => Promise<void>) => { if (busyRef.current || polling || restoring) return; invalidateRestore(); busyRef.current = true; setBusy(label); setError(null); setNotice(null); try { await action(); } catch (err) { setError(err instanceof Error ? err.message : 'This action could not be completed.'); } finally { busyRef.current = false; setBusy(null); } };
  const signIn = async () => { try { if (selectedFile) await rememberFile(selectedFile); } catch { /* The user can select the source again if local storage is unavailable. */ } window.location.href = `/api/login?returnTo=${encodeURIComponent(window.location.pathname + window.location.search)}`; };
  const requireAuthor = () => { if (!user) throw new Error('Sign in before uploading your paper or requesting AI analysis. Your selected file stays local until you choose to upload it.'); };
  const chooseFile = (file?: File) => { if (!file || working) return; const extension = file.name.split('.').pop()?.toLowerCase(); if (!['pdf', 'txt', 'tex'].includes(extension || '')) { setError('Choose a PDF, plain-text (.txt), or LaTeX (.tex) file.'); return; } if (file.size > 5 * 1024 * 1024) { setError('This prototype accepts source files up to 5 MB. A concise summary is a good starting point.'); return; } if (!file.size) { setError('The selected file is empty.'); return; } invalidateRestore(); forgetIntake(); if (source || packet || submission) { setTitle(''); setAuthors(''); setMainClaim(''); setSubjectSlug(''); setJsonDraft(''); } setSelectedFile(file); setSource(null); setPacket(null); setSubmission(null); setJob(null); setApprovedIntent(false); setPublishIntent(false); setShowSource(false); setStep(0); setError(null); setNotice(null); window.history.replaceState({}, '', '/formal-lab'); };
  const upload = async (file: File): Promise<IngestedSource> => { requireAuthor(); const type = file.name.toLowerCase().endsWith('.pdf') ? 'application/pdf' : file.name.toLowerCase().endsWith('.tex') ? 'text/x-tex' : 'text/plain'; const next = await request<IngestedSource>('/sources', { filename: file.name, mimeType: type, base64: await fileBase64(file) }); setSource(next); if (user?.id) retainIntake(recoveryStore, user.id, { sourceId: next.id, ...(validModelId(modelId) ? { modelId } : {}) }); await rememberFile(null).catch(() => {}); return next; };
  const startJob = (next: FormalJob) => { invalidateRestore(); setJob(next); window.history.replaceState({}, '', next.kind === 'process' && next.submissionId ? `/formal-lab?submission=${encodeURIComponent(next.submissionId)}&job=${encodeURIComponent(next.id)}` : `/formal-lab?job=${encodeURIComponent(next.id)}`); if (user?.id) { rememberActiveJob(recoveryStore, user.id, next.id); if (next.kind === 'analyze' && next.sourceId) retainIntake(recoveryStore, user.id, { sourceId: next.sourceId, jobId: next.id, ...(validModelId(next.model?.id || modelId) ? { modelId: (next.model?.id || modelId) as 'current' | 'sol' | 'argon' } : {}) }); } };
  const uploadSelected = () => run('Extracting and numbering the source', async () => { if (!selectedFile) throw new Error('Choose a file first.'); await upload(selectedFile); setNotice('The source was extracted. Inspect its numbered lines, then ask AI to analyze the paper.'); setShowSource(true); });
  const analyzeSource = () => run('Starting the source analysis', async () => { requireAuthor(); requireModel(); const currentSource = source || (selectedFile ? await upload(selectedFile) : null); if (!currentSource) throw new Error('Choose a source file first.'); const next = await request<FormalJob>('/analyze', { sourceId: currentSource.id, modelId, ...(title.trim() ? { title: title.trim() } : {}), ...(authors.trim() ? { authors: authors.trim() } : {}), ...(mainClaim.trim() ? { mainClaim: mainClaim.trim() } : {}), ...(subjectSlug ? { subjectSlug } : {}) }); startJob(next); });
  const loadExample = () => run('Loading the current one-page PDF', async () => { const response = await fetch('/formal-lab/horizon-boundary-summary-current.pdf'); if (!response.ok) throw new Error('The one-page PDF could not be loaded. Please upload your copy.'); const blob = await response.blob(); chooseFile(new File([blob], 'horizon-boundary-summary-2026-10-22.pdf', { type: 'application/pdf' })); setNotice('The current one-page PDF is selected locally. Choose your analysis model below, then click Analyze the complete paper to start.'); workspace.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }); });
  const saveJson = () => run('Saving a new revision', async () => { requireAuthor(); if (!submission) return; let value: FormalPackage; try { value = JSON.parse(jsonDraft); } catch { throw new Error('The exact package contains invalid JSON. Correct it before saving.'); } const next = await request<FormalSubmission>(`/submissions/${encodeURIComponent(submission.id)}/revisions`, { package: value, baseDigest: submission.currentRevision.digest }); takeSubmission(next); setNotice('A new revision was saved. Its source links and checks require a fresh approval.'); });
  const approve = () => run('Recording approval for this exact revision', async () => { requireAuthor(); if (!submission || advancedDirty || !approvedIntent) throw new Error('Save and review the exact revision, then confirm it represents your paper.'); const next = await request<FormalSubmission>(`/submissions/${encodeURIComponent(submission.id)}/approve`, { digest: submission.currentRevision.digest, confirmed: true, publishToField: publishIntent }); takeSubmission(next); setStep(3); });
  const process = () => run('Starting verification and output generation', async () => { requireAuthor(); if (!submission || !approved) throw new Error('Approve the saved revision before running its checks.'); startJob(await request<FormalJob>(`/submissions/${encodeURIComponent(submission.id)}/process`, { digest: submission.currentRevision.digest })); });
  const openLines = (ids: string[]) => { if (!ids.length) return; setHighlight(ids[0]); if (step === 4) setTab('source'); else setShowSource(true); window.setTimeout(() => document.getElementById(`source-line-${ids[0]}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 90); };
  const go = (next: Step) => { if (working) return; if (next > 0 && !packet) return; setStep(next); setError(null); };

  return <div className="fl"><LabHeader signedIn={user ? user.firstName || user.email || 'Signed in' : undefined} loading={authLoading} signIn={signIn} /><main>
    <section className="fl-hero fl-upload-hero"><div className="fl-hero-copy"><div className="fl-eyebrow"><span className="fl-live-dot" /> A SEPARATE EXPERIMENT IN SCIENTIFIC REVIEW</div><h1>From a clear paper<br /><span>to a checkable explanation.</span></h1><p>Drop in a paper. Review the inputs and claims extracted by AI. Approve the exact formulation, then follow the evidence from symbolic verification into a growing subject explanation.</p><div className="fl-hero-actions"><button className="fl-button fl-button-primary" onClick={() => { workspace.current?.scrollIntoView({ behavior: 'smooth' }); fileInput.current?.click(); }} disabled={working}><UploadCloud size={16} /> Upload a paper</button><a className="fl-button fl-button-ghost" href="/formal-lab/subjects/horizon-thermodynamics"><Layers3 size={16} /> Explore the subject account</a></div><p className="fl-hero-footnote">Exact algebra and derivatives · Source-linked coverage · Author approval · Independent checking</p></div><div className="fl-pilot-card"><div className="fl-pilot-top"><span className="fl-pilot-icon"><FileText size={21} /></span><span className="fl-small-caps">TRY THE COMPLETE PIPELINE</span></div><h2>A one-page test of horizon mechanics</h2><p>Use J. T. Tyler’s one-page summary, dated 22 October 2026. Loading the PDF lets you choose a model before starting a fresh analysis.</p><button className="fl-button fl-button-ghost fl-example-upload" onClick={loadExample} disabled={working}><FileText size={14} />Load the one-page PDF</button><a className="fl-prepared-link" href="/formal-lab/horizon-boundary-summary-current.pdf" target="_blank" rel="noopener noreferrer">Open the current source PDF <ExternalLink size={11} /></a><a className="fl-prepared-link" href="/formal-lab?prepared=1">Inspect the prepared scalar baseline <ArrowRight size={11} /></a></div></section>
    <div className="fl-workflow" ref={workspace} id="formal-workflow"><nav className="fl-steps" aria-label="Submission stages">{STEPS.map((item, index) => { const Icon = item.icon; return <button key={item.title} className={`fl-step ${step === index ? 'fl-step-active' : ''}`} aria-current={step === index ? 'step' : undefined} aria-controls="formal-stage-panel" onClick={() => go(index as Step)} disabled={working || (index > 0 && !packet)}><span className="fl-step-circle"><Icon size={16} /></span><span className="fl-step-label"><small>0{index + 1}</small><strong>{item.short}</strong></span></button>; })}</nav>
      {error && <div className="fl-alert fl-alert-error" role="alert"><strong>We couldn’t complete that action.</strong><span><MathText text={error} /></span>{!user && <button className="fl-text-button" onClick={signIn}>Sign in to continue <ArrowRight size={14} /></button>}</div>}
      {notice && <div className="fl-alert fl-alert-info" role="status"><MathText text={notice} /></div>}
      {(busy || restoring) && <div className="fl-busy" role="status"><Loader2 size={17} className="fl-spin" />{busy || 'Restoring your uploaded source'}…</div>}
      {job && (polling || job.status === 'failed') && <section className="fl-job-panel" aria-live="polite"><div className="fl-job-heading">{polling ? <Loader2 size={20} className="fl-spin" /> : <FileText size={20} />}<div><h3>{polling ? (job.kind === 'analyze' ? 'Analyzing the complete source' : 'Verifying and building the outputs') : 'Processing stopped'}</h3><p><MathText text={polling ? `Current stage: ${job.stage}. Uploaded sources and completed drafts are saved. Keep this page open to follow this attempt.` : job.error || 'Processing stopped.'} /></p></div></div><EventLog events={job.events} /></section>}
      <div className={`fl-workspace ${step === 4 ? 'fl-workspace-report' : ''}`}><div className="fl-panel" id="formal-stage-panel" aria-busy={working}>
        <div className="fl-stage-heading"><div className="fl-eyebrow">STAGE 0{step + 1} OF 05</div><h2 id="formal-stage-title" tabIndex={-1}>{STEPS[step].title}</h2><p>{['The source is preserved, hashed and extracted into numbered lines before AI analysis.', 'Review what AI inferred, what the paper states, and what the checker can actually test.', 'Your approval fixes the exact inputs, assumptions, claims and source links to one revision.', 'Run an independent symbolic checker, then generate explanations and a scientific assessment from its actual findings.', 'Inspect the evidence, explanation, review, source coverage and placement in the subject account.'][step]}</p></div>
        {step > 0 && step < 4 && submission && <ModelAttribution formalization={submission.currentRevision.model} />}
        {step === 0 && <><input ref={fileInput} type="file" className="fl-sr-only" accept=".pdf,.txt,.tex,application/pdf,text/plain,text/x-tex" aria-label="Choose a paper file" disabled={working} onChange={event => chooseFile(event.target.files?.[0])} /><div className={`fl-dropzone ${dragging ? 'fl-dropzone-active' : ''} ${selectedFile ? 'fl-dropzone-selected' : ''}`} onDragOver={event => { event.preventDefault(); if (!working) setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={event => { event.preventDefault(); setDragging(false); chooseFile(event.dataTransfer.files[0]); }}><div className="fl-upload-icon">{selectedFile ? <FileText size={26} /> : <UploadCloud size={28} />}</div><h3>{selectedFile ? selectedFile.name : source ? source.filename : 'Drop your paper here'}</h3><p>{selectedFile ? `${(selectedFile.size / 1024).toFixed(0)} KB · ${source ? 'Source extracted' : 'Selected locally; not uploaded yet'}` : source ? `${source.pageCount} ${source.pageCount === 1 ? 'page' : 'pages'} · Source extracted` : 'A concise PDF, LaTeX or plain-text manuscript is a good first submission.'}</p><button className="fl-button fl-button-ghost" onClick={() => fileInput.current?.click()} disabled={working}>{selectedFile || source ? 'Choose another file' : 'Choose a file'}</button><small>PDF, TXT or TEX · Up to 5 MB · Selectable text required for PDF extraction</small></div>
          <details className="fl-details fl-author-guidance"><summary>Clear submission checklist <ChevronDown size={15} /></summary><div className="fl-details-content"><ol><li><strong>Define every quantity.</strong> Give its meaning, units, domain and sign convention; say which variables are independent and what is held fixed.</li><li><strong>Separate inputs from new claims.</strong> Name reused physical laws and cited results, then state what this paper adds.</li><li><strong>Specify the physical setting.</strong> Make boundary conditions, clock normalization, approximations and regimes explicit.</li><li><strong>Show the mathematical steps.</strong> Put one equation step per line where practical and use readable equation numbers so each inference can be referenced.</li><li><strong>Preserve readable notation.</strong> If PDF extraction damages equations, submit the matching LaTeX source as a TEX file.</li><li><strong>Explain what follows.</strong> Say what would follow if the claim is true, why it matters, and how it changes the subject explanation.</li></ol><p>The source coverage and unresolved claims make gaps visible. Clear presentation improves the chance of faithful checks; the physical inputs still need their own justification.</p></div></details>
          <details className="fl-details"><summary>Optional guidance for the AI <ChevronDown size={15} /></summary><div className="fl-details-content fl-form-grid"><label className="fl-field fl-field-wide">Submission title<input value={title} onChange={event => setTitle(event.target.value)} maxLength={300} placeholder="Leave blank to extract from the paper" disabled={working} /></label><label className="fl-field">Author(s)<input value={authors} onChange={event => setAuthors(event.target.value)} maxLength={300} placeholder="Extract from source" disabled={working} /></label><label className="fl-field">Subject area<input value={subjectSlug} onChange={event => setSubjectSlug(event.target.value)} maxLength={100} placeholder="Leave blank for AI to suggest" disabled={working} /></label><label className="fl-field fl-field-wide">The central claim, in your words<textarea rows={3} value={mainClaim} onChange={event => setMainClaim(event.target.value)} maxLength={6000} placeholder="Optional: help disambiguate your intended contribution" disabled={working} /></label></div></details>
          {source && <><div className="fl-source-ready"><CheckCircle2 size={18} /><div><strong>Source extracted and preserved</strong><p>{source.lines.length} numbered lines · {source.pageCount} {source.pageCount === 1 ? 'page' : 'pages'} · SHA-256 {shortDigest(source.sha256)}</p></div><button className="fl-text-button" onClick={() => setShowSource(!showSource)}>{showSource ? 'Hide source' : 'Inspect source'} <ChevronDown size={14} /></button></div>{showSource && <SourceDocument source={source} highlight={highlight} onOpen={openLines} />}</>}
          {analysisModels.length > 0 && <section className="fl-model-picker" aria-labelledby="formal-model-heading"><label className="fl-field" htmlFor="formal-analysis-model"><span id="formal-model-heading">AI analysis model</span><select id="formal-analysis-model" value={modelId} onChange={event => chooseModel(event.target.value)} disabled={working} aria-describedby="formal-model-guidance">{analysisModels.map(model => <option key={model.id} value={model.id} disabled={!model.available}>{model.label} · {model.model}{model.available ? '' : ' — unavailable'}</option>)}</select></label><p id="formal-model-guidance">This model proposes the formalization and generates the explanation and review after verification. SymPy checks the mathematical claims. Choosing a model here applies to a new analysis; saved revisions retain their recorded model.</p><p className="fl-model-config-note">Availability means a provider key is configured. Access to the selected model is checked when analysis starts.</p>{analysisModels.filter(model => !model.available).map(model => <p className="fl-model-unavailable" key={model.id}><strong>{model.label}:</strong> {model.reason || 'The provider is not configured.'}</p>)}</section>}
          <div className="fl-data-note"><LockKeyhole size={15} /><p>{!user ? 'Your selected file stays in this browser. Sign in to upload it and request analysis.' : 'AI analysis sends the source to the selected AI provider. Your submission stays private unless you explicitly choose public field publication when approving.'}</p></div><div className="fl-stage-actions">{!user ? <><span>Sign in to create your own source-linked submission.</span><button className="fl-button fl-button-primary" onClick={signIn} disabled={working}>Sign in to continue <ArrowRight size={15} /></button></> : <><button className="fl-button fl-button-ghost" onClick={uploadSelected} disabled={!selectedFile || Boolean(source) || working}><FileText size={15} /> Extract source first</button><button className="fl-button fl-button-primary" onClick={analyzeSource} disabled={(!selectedFile && !source) || working || modelUnavailable}><Sparkles size={15} /> {job?.kind === 'analyze' && job.status === 'failed' && source?.id === job.sourceId ? 'Retry analysis' : 'Analyze the complete paper'} <ArrowRight size={15} /></button></>}</div><p className="fl-action-footnote">Analysis proposes inputs and accounts for mathematical and non-mathematical statements. Approval and verification happen afterward.</p>
        </>}
        {step === 1 && packet && <><div className="fl-proposal-banner"><Sparkles size={23} /><div><h3>AI proposal, linked to the source</h3><p>Read the formalization as a proposed interpretation of your paper. Unsupported statements remain visible; a neat equation is not evidence that its physical premise is established.</p></div></div>{packet.analysis?.extractionWarnings.length ? <div className="fl-inline-note"><strong>Issues to inspect</strong><ul>{packet.analysis.extractionWarnings.map((item, i) => <li key={i}><MathText text={item} /></li>)}</ul></div> : null}<PackagePreview packet={packet} onOpen={openLines} />{source && <details className="fl-details" open={showSource} onToggle={event => setShowSource(event.currentTarget.open)}><summary>Inspect the numbered source <ChevronDown size={15} /></summary><div className="fl-details-content"><SourceDocument source={source} highlight={highlight} onOpen={openLines} /></div></details>}<div className="fl-stage-actions"><button className="fl-text-button" onClick={() => go(0)}><ArrowLeft size={14} /> Source and intake</button><button className="fl-button fl-button-primary" onClick={() => go(2)}>Review exact revision and approve <ArrowRight size={15} /></button></div></>}
        {step === 2 && packet && submission && <><div className="fl-revision-strip"><div><span>Immutable package</span><strong>Revision {submission.currentRevision.revision}</strong></div><code title={submission.currentRevision.digest}>{shortDigest(submission.currentRevision.digest)}</code><Status value={approved ? 'checked' : 'draft'} /></div><PackagePreview packet={packet} onOpen={openLines} />{source && <details className="fl-details" open={showSource} onToggle={event => setShowSource(event.currentTarget.open)}><summary>Check the source against the proposal <ChevronDown size={15} /></summary><div className="fl-details-content"><SourceDocument source={source} highlight={highlight} onOpen={openLines} /></div></details>}<details className="fl-details fl-advanced"><summary>Advanced: inspect or revise the exact package <ChevronDown size={15} /></summary><p>Edit the proposed inputs, assumptions, claims and explanations here. A changed package is saved as a new revision and requires fresh approval.</p><label className="fl-field">Exact package JSON<textarea className="fl-json-editor" value={jsonDraft} onChange={event => { setJsonDraft(event.target.value); setApprovedIntent(false); }} disabled={working} spellCheck={false} rows={18} /></label><button className="fl-button fl-button-ghost" onClick={saveJson} disabled={!advancedDirty || working}>Save a new revision</button></details><div className="fl-approval"><div className="fl-approval-title"><ShieldCheck size={21} /><h3>Approve the meaning before it is checked</h3></div>{approved ? <p className="fl-approved-message"><CheckCircle2 size={17} />Approved <DateStamp value={submission.currentRevision.approvedAt!} />. Publication consent: {submission.currentRevision.publishConsent ? 'public field contribution authorized' : 'private submission'}.</p> : <><label className="fl-approval-checkbox"><input type="checkbox" checked={approvedIntent} onChange={event => setApprovedIntent(event.target.checked)} disabled={advancedDirty || working} /><span>I reviewed the source, proposed inputs, assumptions and claims. This exact revision accurately represents what I want the system to check.</span></label><label className="fl-approval-checkbox fl-publish-checkbox"><input type="checkbox" checked={publishIntent} onChange={event => setPublishIntent(event.target.checked)} disabled={advancedDirty || working} /><span><strong>Optional public contribution:</strong> publish this revision’s source file, formalization, verification and generated outputs, and allow eligible results to contribute to the public subject explanation.</span></label><p>The publication box is optional and starts unchecked. Approval applies to the saved SHA-256 digest; future edits require a new approval.</p></>}<div className="fl-approval-actions">{advancedDirty ? <button className="fl-button fl-button-primary" onClick={saveJson} disabled={working}>Save your changes first</button> : approved ? <button className="fl-button fl-button-primary" onClick={() => go(3)}>Continue to verification <ArrowRight size={15} /></button> : <button className="fl-button fl-button-primary" onClick={user ? approve : signIn} disabled={!approvedIntent || working}>Approve this exact revision <Check size={15} /></button>}</div></div></>}
        {step === 3 && packet && submission && <><div className="fl-checker-card"><div className="fl-checker-icon"><ShieldCheck size={35} /></div><div className="fl-eyebrow">REAL COMPUTATION, FOLLOWED BY EVIDENCE-LINKED OUTPUTS</div><h3>{catalog?.capabilities.checker || 'Independent symbolic checker'}</h3><p>The fixed checker compares each formal claim, tracks dimensions and required domains, and returns an explicit result. AI then builds the explanation and review from the actual report.</p><div className="fl-checker-scopes">{(catalog?.capabilities.scope || ['Exact algebra', 'Scalar derivatives', 'Dimensional consistency']).map(item => <span key={item}><Check size={13} /><MathText text={item} /></span>)}</div></div><div className="fl-verification-readiness"><div><span>Exact revision</span><strong>{submission.currentRevision.revision}</strong></div><div><span>Author approval</span><strong>{approved ? 'Recorded for this digest' : 'Required'}</strong></div><div><span>Publication</span><strong>{submission.currentRevision.publishConsent ? 'Authorized after checks' : 'Private'}</strong></div><div><span>Package digest</span><code>{shortDigest(submission.currentRevision.digest)}</code></div></div><div className="fl-scope-note"><h3>A complete account of coverage, rather than a blanket verdict</h3><p>Mathematical claims receive individual checks. Definitions, adopted physical inputs, interpretations and claims beyond the checker’s language retain their own labels and open questions.</p></div><div className="fl-stage-actions"><button className="fl-text-button" onClick={() => go(2)}><ArrowLeft size={14} /> Review approval</button><button className="fl-button fl-button-primary" onClick={process} disabled={!approved || working}><ShieldCheck size={16} />Verify and build outputs <ArrowRight size={15} /></button></div></>}
        {step === 4 && (submission?.currentRevision.verification ? <OutputReport submission={submission} tab={tab} setTab={setTab} source={source} job={job} highlight={highlight} onOpen={openLines} /> : <Unavailable text="Approve the formalization and run verification to see the evidence-linked results here." />)}
      </div><aside className="fl-sidebar"><div className="fl-sidebar-card"><div className="fl-eyebrow">YOUR WORKSPACE</div><h3>{submission ? 'Source-linked submission' : source ? 'Extracted source' : 'A new submission'}</h3><p className="fl-sidebar-title">{packet ? <MathText text={packet.title} /> : selectedFile?.name || source?.filename || 'Start with a concise paper that names its inputs and central claim.'}</p><dl><div><dt>Source</dt><dd>{source ? `${source.lines.length} lines` : 'Not uploaded'}</dd></div><div><dt>Exact claims</dt><dd>{packet?.claims.length ?? '—'}</dd></div><div><dt>Source statements</dt><dd>{packet?.analysis?.coverage.length ?? '—'}</dd></div><div><dt>Approval</dt><dd>{approved ? 'Recorded' : 'Awaiting author'}</dd></div><div><dt>Verification</dt><dd>{submission?.currentRevision.verification ? statusLabel(submission.currentRevision.verification.status) : 'Not run'}</dd></div></dl>{submission && <div className="fl-digest-caption"><span>Current package</span><code title={submission.currentRevision.digest}>{shortDigest(submission.currentRevision.digest)}</code></div>}{working && <span className="fl-sidebar-working"><Loader2 size={12} className="fl-spin" />Processing in progress</span>}</div>
        {user && submissions.length > 0 && <div className="fl-sidebar-card"><h3>Your saved submissions</h3><div className="fl-saved-list">{submissions.map(item => <button key={item.id} className={submission?.id === item.id ? 'fl-saved-active' : ''} onClick={() => run('Opening submission', () => openSubmission(item.id))} disabled={working}><strong><MathText text={item.title} /></strong><span>Revision {item.currentRevision.revision} · {item.currentRevision.approvedAt ? 'approved' : 'draft'}</span></button>)}</div></div>}
        <div className="fl-sidebar-note"><Layers3 size={20} /><h3>One paper, then a subject</h3><p>Eligible results can join a shared explanation, with the source and checked equations always reachable. Author publication consent is required.</p><a href="/formal-lab/subjects/horizon-thermodynamics">Horizon thermodynamics <ArrowRight size={12} /></a></div><div className="fl-sidebar-note"><FlaskConical size={19} /><h3>What establishes a physical input?</h3><p>A derivation from accepted theory with explicit boundary conditions, agreement with independent formulations, and where applicable tests against observation. Symbolic consistency is one part of that assessment.</p><a href="https://docs.sympy.org/latest/index.html" target="_blank" rel="noopener noreferrer">About SymPy <ExternalLink size={12} /></a></div>
      </aside></div>
    </div><footer className="fl-footer"><span><FlaskConical size={14} />Formal Lab · Prototype v2</span><p>Source → proposed claims → author approval → independent checks → linked explanations.</p><a href="/">Return to the main site <ArrowRight size={13} /></a></footer>
  </main></div>;
}
export default function FormalLabPage() { const subject = window.location.pathname.match(/^\/formal-lab\/subjects\/([^/]+)\/?$/); if (subject) return <SubjectPage slug={decodeURIComponent(subject[1])} />; if (new URLSearchParams(window.location.search).get('prepared') === '1') return <FormalPreparedExample />; return <SubmissionWorkspace />; }
